import{_ as t,a}from"./chunks/piwi-ecosystem.DuNXw409.js";import{_ as r,o as i,c as o,ak as s}from"./chunks/framework.sV-XtlWr.js";const m=JSON.parse('{"title":"What Piwi does","description":"","frontmatter":{"title":"What Piwi does","lang":"en-US"},"headers":[],"relativePath":"guide/what-piwi-does.md","filePath":"guide/what-piwi-does.md","lastUpdated":1788713927000}'),n={name:"guide/what-piwi-does.md"};function h(l,e,d,u,p,f){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-piwi-does" tabindex="-1">What Piwi does <a class="header-anchor" href="#what-piwi-does" aria-label="Permalink to &quot;What Piwi does&quot;">​</a></h1><p>Playwright&#39;s HTML report is excellent, and it lasts exactly until the next build. Piwi keeps every run instead — every trace and report — and then does something with them: it groups the failures by root cause, scores the flaky tests by what they cost, and finds the locator you should have used. Self-hosted, MIT, zero telemetry.</p><p>Everything in the product is in service of <strong>three jobs, in this order</strong>. It&#39;s also the test for whether a feature belongs here at all: one that strengthens none of them is an argument against building it.</p><h2 id="the-three-jobs" tabindex="-1">The three jobs <a class="header-anchor" href="#the-three-jobs" aria-label="Permalink to &quot;The three jobs&quot;">​</a></h2><ol><li><strong>Keep the history.</strong> CI deletes every report it makes. Piwi keeps every run, trace and report, so &quot;has this always been flaky?&quot; and &quot;did my fix hold?&quot; are answerable at all.</li><li><strong>Explain the failures.</strong> Group them by root cause so forty red tests become three problems, score the flaky ones by the CI minutes they actually waste, and — optionally — have an LLM explain a cluster against your real git diff.</li><li><strong>Hand back a fix.</strong> A ranked replacement locator, a validated patch, an owner, and the command that verifies the work. The point is to leave with something to <em>do</em>, not just something to read.</li></ol><p>Everything else — analytics, notifications, the CI gate, PR feedback, the MCP server, the desktop app — is a delivery route for those three. The dashboard follows the same ranking: it leads with results and failures, and the supporting lenses sit behind them.</p><h2 id="the-loop-it-serves" tabindex="-1">The loop it serves <a class="header-anchor" href="#the-loop-it-serves" aria-label="Permalink to &quot;The loop it serves&quot;">​</a></h2><p>Explaining a failure is the heart of it, and it&#39;s a loop: gather the evidence, group the failures by cause, explain why they broke, hand back a fix, then verify the fix actually held.</p><figure><img src="'+t+'" alt="The failure-explaining loop: gather evidence, group into clusters, diagnose, hand back a fix, and a verification arrow back to the start"><figcaption>The loop the whole product serves — gather, group, explain, hand back, then verify the fix held.</figcaption></figure><p>Each step is a page on this site: the <a href="/features/evidence.html">failing execution</a> and its <a href="/features/evidence.html#clues">evidence</a>, <a href="/features/failure-clusters.html">failure clusters</a>, <a href="/features/ai-diagnosis.html">AI diagnosis</a>, <a href="/features/locator-healing.html">locator healing</a> and <a href="/features/auto-heal.html">auto-heal PRs</a>, and the <a href="/features/ai-diagnosis.html#did-the-fix-work">fix verification</a> that closes it.</p><h2 id="two-rules" tabindex="-1">Two rules <a class="header-anchor" href="#two-rules" aria-label="Permalink to &quot;Two rules&quot;">​</a></h2><p>Two rules run through every feature, and they&#39;re worth knowing before you adopt it:</p><ol><li><strong>The tool proposes, the developer decides.</strong> Piwi never rewrites a test, never merges a fix, and never applies a patch on its own. It gathers, ranks and suggests; the last step is always yours. Even <a href="/features/auto-heal.html">auto-heal PRs</a> only <em>open</em> a pull request for you to review and merge.</li><li><strong>Deterministic first, AI second.</strong> Anything that has to be right every time — clustering, flaky scoring, locator ranking, fix verification — is computed without a model. AI sits on top, where a suggestion is enough, and what it produces is checked against your real source before you see it. AI is off by default and brings your own key.</li></ol><h2 id="the-pieces" tabindex="-1">The pieces <a class="header-anchor" href="#the-pieces" aria-label="Permalink to &quot;The pieces&quot;">​</a></h2><p>Piwi is a reporter that uploads from your Playwright run, a server (or the <a href="/features/desktop.html">desktop app</a>) that keeps and analyzes the results, and a set of ways to reach them — the <a href="/features/extension.html">browser extension</a>, an <a href="/features/mcp.html">MCP server</a> and <a href="/features/mcp.html#agent-skills">agent skills</a> for coding agents, <a href="./ci.html#pull-request-feedback">SCM providers</a> for PR feedback and healing, and <a href="/features/notifications.html">notifications</a>.</p><figure><img src="'+a+'" alt="The Piwi pieces: a Playwright run and instrumented app feed one server or the desktop app, with the browser extension, coding agents, SCM providers and notifications arranged around it"><figcaption>The reporter and your instrumented app feed one server (or the desktop app); the extension, agents, SCM providers and notifications sit around it.</figcaption></figure><h2 id="what-it-isn-t" tabindex="-1">What it isn&#39;t <a class="header-anchor" href="#what-it-isn-t" aria-label="Permalink to &quot;What it isn&#39;t&quot;">​</a></h2><p>Trust is the point, so the limits are stated plainly, not buried:</p><ul><li><strong>Playwright only, by design.</strong> The ingest API, trace handling, step analytics and locator healing are all built around Playwright&#39;s model. If you need to aggregate many frameworks (JUnit, pytest, Cypress) into one place, <a href="./comparison.html">ReportPortal or Allure</a> fit better.</li><li><strong>Pre-1.0.</strong> Patch and minor releases can carry breaking changes, and the database schema moves with them — read <a href="/operate/upgrading.html">Upgrading</a> before you bump a tag.</li><li><strong>Not an &quot;ask AI&quot; button.</strong> Diagnosis is optional, grounded in your diff, and never in the write path.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./getting-started.html">Getting started</a> — pick a path and land your first run</li><li><a href="./concepts.html">Core concepts</a> — the vocabulary (run, execution, cluster, fingerprint, baseline)</li><li><a href="/reference/feature-map.html">Feature map</a> — everything Piwi does, what each thing needs, and where it lives</li><li><a href="./comparison.html">Why Piwi? (comparison &amp; FAQ)</a> — how it compares, and whether it&#39;s the right tool for you</li><li><a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">Live demo</a> — the real app on seeded data, entirely in your browser</li></ul>',21)])])}const w=r(n,[["render",h]]);export{m as __pageData,w as default};
